// Original code submitted for review
public class OrderService {
    public void processOrder(Long orderId) {
        var order = orderRepository.findById(orderId).get(); // Reviewer: what if order doesn't exist?
        order.setStatus("PROCESSED");
        orderRepository.save(order);
        // Reviewer: missing notification to customer?
    }
}

// After review feedback applied
public class OrderService {
    public void processOrder(Long orderId) {
        var order = orderRepository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId)); // Fixed: handle missing order

        order.setStatus(OrderStatus.PROCESSED);
        orderRepository.save(order);

        notificationService.sendOrderConfirmation(order); // Added: notify customer
    }
}

// Reviewing this Spring Boot controller method
@RestController
public class UserController {
    @Autowired
    private UserRepository userRepository;

    @GetMapping("/users/{id}")
    public User getUser(@PathVariable String id) { // Review: id should be Long, not String
        var user = userRepository.findById(Long.parseLong(id)).get(); // Review: .get() throws exception, use orElseThrow()
        // Review: missing @Transactional if lazy-loading associations
        return user; // Review: exposing entity directly, should use DTO to hide password field
    }
}

// After review feedback applied
@RestController
public class UserController {
    private final UserRepository userRepository;

    public UserController(UserRepository userRepository) { // Constructor injection instead of field injection
        this.userRepository = userRepository;
    }

    @GetMapping("/users/{id}")
    public UserDTO getUser(@PathVariable Long id) { // Fixed: proper type
        var user = userRepository.findById(id)
            .orElseThrow(() -> new UserNotFoundException(id)); // Fixed: explicit error handling
        return new UserDTO(user.getId(), user.getName(), user.getEmail()); // Fixed: DTO hides password
    }
}

// Poor review comment example:
// "This is bad, rewrite it"

public List<Order> getActiveOrders(Long customerId) {
    List<Order> allOrders = orderRepository.findByCustomerId(customerId);
    List<Order> result = new ArrayList<>();
    for (Order order : allOrders) {
        if (order.getStatus().equals("ACTIVE")) { // Poor comment: "don't use strings"
            result.add(order);
        }
    }
    return result;
}

// Good review comment example:
// "Consider using a database query with a status filter instead of loading all orders into memory.
// For customers with thousands of orders, this could cause performance issues.
// Example: orderRepository.findByCustomerIdAndStatus(customerId, OrderStatus.ACTIVE)
// Also, use the OrderStatus enum instead of string literals to prevent typos.
// nit: Stream API could make this more concise if you prefer that style."

public List<Order> getActiveOrders(Long customerId) {
    return orderRepository.findByCustomerIdAndStatus(customerId, OrderStatus.ACTIVE); // Clean solution
}

// Initial PR - reviewer leaves comment:
// "This loop loads all orders into memory. For customers with thousands of orders,
// this could cause OutOfMemoryError. Can we add pagination or filter at database level?"

public List<Order> getRecentOrders(Long customerId) {
    return orderRepository.findByCustomerId(customerId).stream()
        .filter(o -> o.getCreatedDate().isAfter(LocalDate.now().minusDays(30)))
        .toList();
}

// Good response in PR comments:
// "You're right, I didn't think about customers with lots of historical orders.
// I'll add a date parameter to the repository query. Should I also add a limit,
// or is filtering by date enough?"

// Updated code after discussion:
public List<Order> getRecentOrders(Long customerId) {
    var thirtyDaysAgo = LocalDate.now().minusDays(30).atStartOfDay();
    return orderRepository.findByCustomerIdAndCreatedDateAfter(
        customerId, 
        thirtyDaysAgo
    ); // Database now filters, much more efficient
}

