// GOOD APPROACH: split into focused PRs

// PR #1 (50 lines): Add database table and entity
@Entity
public class Discount {
    @Id @GeneratedValue
    private Long id;
    private String code;
    private BigDecimal percentage;
    private LocalDate expiresAt;
}

// PR #2 (80 lines): Repository and basic service methods
public class DiscountService {
    public Optional<Discount> findByCode(String code) {
        return discountRepository.findByCode(code)
            .filter(d -> d.getExpiresAt().isAfter(LocalDate.now())); // Only valid discounts
    }
}

// PR #3 (120 lines): Integrate with order processing behind feature flag
@Service
public class OrderService {
    @Value("${features.discounts.enabled}")
    private boolean discountsEnabled; // Feature flag

    public Order createOrder(OrderRequest request) {
        var order = new Order(request.getItems());
        if (discountsEnabled && request.getDiscountCode() != null) {
            applyDiscount(order, request.getDiscountCode()); // New logic behind flag
        }
        return orderRepository.save(order);
    }
}

// Code submitted for review
@RestController
public class ProductController {
    @Autowired
    private JdbcTemplate jdbc; // Review: should use repository pattern, not raw JDBC

    @GetMapping("/products/search")
    public List<Map<String, Object>> search(@RequestParam String name) {
        // Review: SQL injection vulnerability! User input directly in query
        String sql = "SELECT * FROM products WHERE name LIKE '%" + name + "%'";
        return jdbc.queryForList(sql); // Review: returns Map, should use proper DTO
    }

    @PostMapping("/products")
    public void create(@RequestBody Product product) { // Review: no validation, no return value
        // Review: no error handling - what if database is down?
        String sql = "INSERT INTO products (name, price) VALUES (?, ?)";
        jdbc.update(sql, product.getName(), product.getPrice());
        // Review: no test for this endpoint in the PR
    }
}

