// GOOD: sequence of small focused commits

// Commit 1: "Add Discount entity and repository"
@Entity
public class Discount {
    @Id @GeneratedValue
    private Long id;
    private String code;
    private BigDecimal percentage;
}

// Commit 2: "Add discount validation logic"
public class DiscountService {
    public void validateDiscount(String code) {
        var discount = discountRepository.findByCode(code)
            .orElseThrow(() -> new InvalidDiscountException(code));
        if (discount.isExpired()) {
            throw new ExpiredDiscountException(code);
        }
    }
}

// Commit 3: "Integrate discount into order creation"
public Order createOrder(OrderRequest request) {
    var order = new Order(request.getItems());
    if (request.getDiscountCode() != null) {
        applyDiscount(order, request.getDiscountCode()); // New integration point
    }
    return orderRepository.save(order);
}

// Each commit: 30-80 lines, one clear purpose, easy to review and revert
